from taf.config.testline.pdu import ATEN
from taf.config.testline import CommonUnit, RealEnb, Airscale, CoreUnit
from taf.rfrl.procedures.resources.python.logger import (
    log_env_state,
    log_result,
    log_operation,
    log_step,
    log_iteration
)
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine

from taf.rfrl.procedures.resources.python.config_validator.exceptions import (
    IncorrectBtsId,
    NoMplaneEnbAddressFound,
    CapacityUnitsNotFound,
    NoTestPcConnected,
    ConnectionsListNotDefined,
    EnbConnectionsNotInstanceRealEnb,
    SmodNotConnectedToPdu,
    CapacityUnitAddrNotFound,
    CapacityUnitsRusNotFound,
    NoGnbRusDetected,
    NotUniqueRuPduPortDetected,
    NoPduPortDefiniedForRu,
    NoPdusDetected,
    AtenModelAttributeError,
    SmodHwTypeNotDefined,
    BBmodHwTypeNotDefined,
    RadioTypeNotConfigured,
    EnbSystemModuleNotFound,
    EnbSystemModuleNotAirscaleInstance,
    EnbSmodNotAList,
    EnbSmodNotCommonUnitInstance,
    SmodSerialNumberNotDefined,
    BBmodSerialNumberNotDefined,
    RmodSerialNumberNotDefined,
    EnbRMSNotFound,
    EnbNotConfigured,
    CoreUnitNotEmptyCapacityUnits,
    SecondConfigGnbNotInDefaultConfig,
    SecondConfigEnbNotInDefaultConfig,
    SecondConfigTestPcAddrNotFound,
    SecondConfigSmodNotFound,
    SecondConfigBbmodNotFound,
    SecondConfigRmodNotFound,
    CouldNotFindBtsType,
)


class Config:
    """ Representation of testline configuration __init__ file """

    def __init__(self, tl):
        self.tl = None
        self.gnbs = []
        self.topology = None
        self.enbs = []
        self.pdus = None
        self.test_pcs = None
        self.ues = None
        self.gnb_smods = []
        self.enb_smods = []
        self.gnb_rus = []
        self.lmi_connected = None
        self.enb_rus = []
        self.test_line = TestLine()
        self._load(tl=tl)

    def __ge__(self, second_config):
        """
        Validates whether second config is subconfiguration or equal to default init file
        :param second_config: Config instance for second configuration
        :type second_config: Config

        :raises SecondConfigGnbNotInDefaultConfig: when gnb from second config could not be found
                                                   in default init file
        :raises SecondConfigEnbNotInDefaultConfig: when enb from second config could not be found
                                                   in default init file
        :raises SecondConfigTestPcAddrNotFound: when test pc from second config could not be found
                                                in default init file
        :raises SecondConfigSmodNotFound: when smod from second config could not be found in default init file
        :raises SecondConfigBbmodNotFound: when bbmod from second config could not be found in default init file
        """
        if self.gnbs and (not hasattr(second_config, 'gnbs') or not second_config.gnbs):
            return all([
                self._validate_second_config_test_pcs_are_subset(second_config.test_pcs),
                self._validate_second_config_smods_are_subset(second_config.enb_smods, "ENB"),
                self._validate_second_config_bbmods_are_subset(second_config.all_bbmods),
                self._validate_second_config_rmods_are_subset(second_config.enb_rus, "ENB")])
        else:
            return all([
                self._validate_second_config_gnbs_are_subset(second_config.gnbs),
                self._validate_second_config_enbs_are_subset(second_config.enbs),
                self._validate_second_config_test_pcs_are_subset(second_config.test_pcs),
                self._validate_second_config_smods_are_subset(second_config.gnb_smods, "GNB"),
                self._validate_second_config_smods_are_subset(second_config.enb_smods, "ENB"),
                self._validate_second_config_bbmods_are_subset(second_config.all_bbmods),
                self._validate_second_config_rmods_are_subset(second_config.gnb_rus, "GNB"),
                self._validate_second_config_rmods_are_subset(second_config.enb_rus, "ENB")])

    def validate(self):
        """
        Validates testline configuration's __init__ file. Validation steps are going through:
        1. Test PCs;
        2. GNB;
        3. ENB (if '_ENB' present in the line's topology);
        4. System modules;
        5. Baseband modules;
        6. Radio Units;
        7. PDUs;

        To find out more about validation steps of certain unit mentioned above please go to dedicated method's docs.

        :raises: NoTestPcConnected exception if any of test pc mentioned in `test_pcs` list does not have
                 `connections` param.

        :raises: ConnectionsListNotDefined exception if any of test pc mentioned in `test_pcs` list does not have
                 list of `connections` param.

        :raises: ConnectionsListNotDefined exception if any of test pc mentioned in `test_pcs` list have empty list of
                 `connections` param.

        :raises: ConnectionsListNotDefined exception if any of test pc mentioned in `test_pcs` list does not have
                 one element list of `connections` param.

        :raises: EnbConnectionsNotInstanceRealEnb exception if enb test pc mentioned in `test_pcs` list does not have
                 `connections` attribute RealEnb instance assigned.

        :raises: EnbSystemModuleNotFound exception if ENB's representation does not have `system module` attribute;

        :raises: EnbSystemModuleNotAirscaleInstance exception if `system_module` does not have Airscale instance;

        :raises: IncorrectBtsId exception if `global_instance_id` or `instance_id` is None;

        :raises: NoMplaneEnbAddressFound exception if there is no `oam_ip` or `m_plane` attribute.

        :raises: IncorrectNrBtsId exception if GNB `instance_id` is greater than number of testline's GNBs.

        :raises: CapacityUnitsNotFound exception if any system module object has not defined or None
                 `capacity_units` attribute;

        :raises: EnbSmodNotAList exception if enb system module is not a one element list;

        :raises: EnbSmodNotCommonUnitInstance exception if enb system module is not CommonUnit instance;

        :raises: SmodNotConnectedToPdu exception if any system module has `pdu_port` attribute not defined or None.

        :raises: CapacityUnitAddrNotFound exception if any baseband module has ip's `addr`
                 attribute not defined or None.

        :raises: CapacityUnitsRusNotFound exception if despite the fact that all RUs have lmi board's parameter
                 configured, there is no proper connection between baseband module and ru object (via `rus` attr).

        :raises: NoGnbRusDetected exception if `rus` list in GNB's DU object is not defined or None.

        :raises: RadioTypeNotConfigured exception if attribute `radio_type` is not defined or None.

        :raises: NoPduPortDefiniedForRu exception if any radio unit object in `rus` list has `pdu_port`
                 not defined or None.

        :raises: NotUniqueRuPduPortDetected exception if any radio unit object in `rus` list has not got unique
                 `pdu_port` attribute.

        :raises: NoPdusDetected exception if tl.pdus list is empty.

        :raises: AtenModelAttributeError exception if there will be any ATEN PDU object with `model` attribute
                 mistakenly defined.

        :raises: SmodHwTypeNotDefined exception if smods's hardware_type parameter is not set.

        :raises: BBmodHwTypeNotDefined exception Raised when bbmod's hardware_type parameter is not set.

        :raises: CouldNotFindBtsType when there is no gnbs nor enbs objects in init file.
        """
        self._validate_test_pcs()

        bts_list = self._get_bts_list()

        if "GNB" in bts_list:
            self._validate_gnb()
            self._validate_gnb_ru_units()

        if "ENB" in bts_list or "_ENB" in self.topology:
            self._validate_enb()

        for bts_type in bts_list:
            self._validate_smod_units(bts_type=bts_type)
            self._validate_bbmod_units(bts_type=bts_type)

        self._validate_pdus()

    @property
    def all_bbmods(self):
        return self._get_all_bbmods()

    def _load(self, tl):
        self.tl = tl
        self.topology = tl.tl_cloud_topology

        try:
            self.gnbs = tl.gnbs
        except TypeError:
            pass
        if self.gnbs:
            self.gnb_smods = self.test_line.get_smods_configs(custom_init=tl)
            self.gnb_rus = self.test_line.get_radios_configs(custom_init=tl)

        self.enbs = tl.enbs if tl.enbs is not None else []
        if self.enbs:
            self.enb_smods = self.test_line.get_smods_configs(bts_type='ENB', custom_init=tl)
            self.enb_rus = self.test_line.get_radios_configs(bts_type='ENB', custom_init=tl)

        self.pdus = tl.pdus
        self.test_pcs = tl.test_pcs

        try:
            self.ues = tl.ues
        except TypeError:
            pass

        self.lmi_connected = self._is_lmi_connected_to_all_rus()

    def _validate_test_pcs(self):
        """
        Validates if test PCs representation in testline configuration file meets certain assertions:

        1. All Test PCs instances have `connections`;
        2. Attribute `connections` cannot be None or empty list or not one element list;
        3. Attribute `connections` from enb test PC should have RealEnb or CommonUnit instance assigned.

        :raises: NoTestPcConnected exception if any of test pc mentioned in `test_pcs` list does not have
                 `connections` param.
        :raises: ConnectionsListNotDefined exception if any of test pc mentioned in `test_pcs` list does not have
                 list of `connections` param.
        :raises: ConnectionsListNotDefined exception if any of test pc mentioned in `test_pcs` list have empty list of
                 `connections` param.
        :raises: ConnectionsListNotDefined exception if any of test pc mentioned in `test_pcs` list does not have
                 one element list of `connections` param.
        :raises: EnbConnectionsNotInstanceRealEnb exception if enb test pc mentioned in `test_pcs` list does not have
                 `connections` attribute RealEnb or CommonUnit instance assigned.
        """
        log_operation("Validating Test PCs in progress...")

        for test_pc in self.test_pcs:
            log_step("Validating: {0}".format(test_pc))

            if not hasattr(test_pc, 'connections') or not test_pc.connections:
                raise NoTestPcConnected("Your TestPC does not have mandatory `connections` "
                                        "attribute, please add Your connected system module object here.")

            if not isinstance(test_pc.connections, list) or not len(test_pc.connections) == 1:
                raise ConnectionsListNotDefined("Your TestPC mandatory `connections` attribute "
                                                "is not a list or not one element list, "
                                                "please review Your init file.")
        if self.enbs:
            if not any(isinstance(test_pc.connections[0], RealEnb) or isinstance(test_pc.connections[0], CommonUnit)
                       or isinstance(test_pc.connections[0], CoreUnit)
                       for test_pc in self.test_pcs):
                raise EnbConnectionsNotInstanceRealEnb("Your Enb TestPC `connections` attribute does not have"
                                                       "RealEnb or CommonUnit or CoreUnit instance assigned.")

    def _validate_gnb(self):
        """
        Validates if GNB's representation in testline configuration file meets certain assertions:
        1. GNB's `global_instance_id` and `instance_id` attributes cannot be None;

        :raises: IncorrectBtsId exception if first condition won't be met.
        """
        log_step("Validating if GNB has properly configured global bts id and instance id...")

        for gnb in self.gnbs:

            if not gnb.global_bts_id or not gnb.instance_id:
                raise IncorrectBtsId("Testline configuration does not have defined `global_bts_id` or `instance_id` "
                                     "attribute in GNB object!")

            log_env_state("Read GNB global bts id: {0}\n"
                          "Read GNB instance id: {1}".format(gnb.global_bts_id, gnb.instance_id))

        log_result("Validation of GNB succeeded!")

    def _validate_enb(self):
        """
        Validates if ENB's representation in testline configuration file meets certain assertions:
        1. Checks if ENB object is configured;
        2. ENB's representation should have `system_module` attribute;
        3. Attribute `system_module` should have Airscale instance assigned;
        4. ENB's `global_instance_id` and `instance_id` attributes cannot be None;
        5. If __init__ file contains information about UE, then ENB's `oam_ip` or `m_plane`
           attribute must be set (not None);

        :raises: MissingEnbObject exception if there's _ENB in line's topology but there's no ENB object configured;
        :raises: EnbSystemModuleNotFound exception if ENB's representation does not have `system module` attribute;
        :raises: EnbSystemModuleNotAirscaleInstance exception if `system_module` does not have Airscale instance;
        :raises: IncorrectBtsId exception if `global_instance_id` or `instance_id` is None;
        :raises: NoMplaneEnbAddressFound exception if there is no `oam_ip` or `m_plane` attribute.
        :raises: EnbRMSNotFound exception if there is no 'rms' attribute.
        """
        log_step("Validating if ENB has properly configured system module...")

        if not self.enbs:
            raise EnbNotConfigured("Testline's topology indicates that it is NSA, yet no enb object was configured.")

        for enb in self.enbs:
            if not hasattr(enb, 'system_module') or not enb.system_module:
                raise EnbSystemModuleNotFound("Testline configuration does not have defined `system module` attribute "
                                              "in ENB object. Please review Your init file!")

            if not isinstance(enb.system_module, Airscale):
                raise EnbSystemModuleNotAirscaleInstance(
                    "Testline configuration with ENB `system module` attribute "
                    "does not have `Airscale` instance. Please review Your init file!")

            log_step("Validating if ENB has properly configured radio modules...")

            if not hasattr(enb, 'rms'):
                raise EnbRMSNotFound("There is no `rms` list defined inside eNB's object please fix Your init "
                                     "file and try again.")

            log_step("Validating if ENB has properly configured global bts id and instance id...")

            if not enb.global_bts_id or not enb.instance_id:
                log_env_state("ENB object: {0}".format(enb))

                raise IncorrectBtsId("Testline configuration does not have defined `global_bts_id` or `instance_id` "
                                     "attribute in ENB object!")

            log_env_state("Read ENB global bts id: {0}\n"
                          "Read ENB instance id: {1}".format(enb.global_bts_id, enb.instance_id))

            if self.ues:
                log_operation("UEs have been detected - validating if m-plane address is set in ENB object...")
                log_env_state("Detected UEs: {0}".format(self.ues))

                if not (enb.oam_ip or hasattr(enb, 'm_plane')):
                    raise NoMplaneEnbAddressFound("Management plane address in ENB configuration representation could"
                                                  " not be found! Please add `oam_ip` attribute to Your ENB "
                                                  "in init as it is needed for l3call tests (UEs were detected)")

                log_result("Management plane address validation succedded!")

        log_result("Validation of ENB succeeded!")

    def _validate_smod_units(self, bts_type):
        """
        Validates system modules in provided BTS Type. Conditions to be met:
        1. Enb system module should be assigned to common_units attribute as a one element list;
        2. Enb system module should be CommonUnit instance;
        3. System module equal ASOE has empty list of `capacity_units`;
        4. All system modules objects must have non-empty, not-None `capacity_units` attribute;
        5. All system modules must have `pdu_port` attribute with particular pdu port attached to it;
        6. Smod's hardware_type parameter is not None.
        7. Smod's serial_number parameter is not None.

        :param bts_type: Type of BTS in which system modules are connected - might be "GNB" or "ENB";
        :type bts_type: str
        :raises: EnbSmodNotAList exception if enb system module is not a one element list;
        :raises: EnbSmodNotCommonUnitInstance exception if enb system module is not CommonUnit instance;
        :raises: CapacityUnitsNotFound exception if third condition won't be met;
        :raises: SmodNotConnectedToPdu exception if fourth condition won't be met;
        :raises: SmodHwTypeNotDefined exception if smods's hardware_type parameter is not set.
        :raises: SmodSerialNumberNotDefined exception if smod's serial_number parameter is not set.
        :raises: AsoeNotEmptyCapacityUnits exception if smod's equal asoe and capacity units is not empty list.
        """
        log_operation("Validating {0} System Modules...".format(bts_type))

        if self.enb_smods:
            if not isinstance(self.enb_smods, list):
                raise EnbSmodNotAList(
                    "Your ENB system module assigned to `common_unit` attribute is "
                    "not a list, please review Your init file!")
            for enb_smod in self.enb_smods:
                if not isinstance(enb_smod, CommonUnit) and not isinstance(enb_smod, CoreUnit):
                    raise EnbSmodNotCommonUnitInstance(
                        "Your ENB system module assigned to `common_unit` attribute is "
                        "not CommonUnit or CoreUnit instance, please review Your init file!")

        smods = self.gnb_smods if bts_type == 'GNB' else self.enb_smods
        log_env_state("List of system modules read from __init__: {0}".format(smods))

        for smod in smods:

            log_iteration("System module that is being validated: {0}".format(smod))

            if isinstance(smod, CoreUnit):
                log_step(f"System module {smod.hardware_type} is CoreUnit instance, "
                         f"skipping `capacity_units` attribute validation.")
            elif smod.hardware_type in ['ASOE', 'ASOG', 'ASOH']:
                if not len(smod.capacity_units) == 0:
                    raise CoreUnitNotEmptyCapacityUnits(f"Your system module is equal to {smod.hardware_type}, "
                                                        "`capacity_units` attribute should "
                                                        "be an empty list, please review Your init file!")
            else:
                if not hasattr(smod, 'capacity_units') or not smod.capacity_units:
                    raise CapacityUnitsNotFound("Your system module does not have mandatory `capacity_units` "
                                                "attribute (or it is None), please review Your init file!")

                log_step("`capacity_units` list detected.")

                log_step("Baseband modules detected inside `capacity_units` list.")

            if bts_type == 'GNB' and not smod.hardware_type:
                raise SmodHwTypeNotDefined("It seems like Your system module does not have `hardware_type` attribute,"
                                           " please review Your init file!")

            log_step("Smod hw type is defined correctly.")

            if not smod.serial_number:
                raise SmodSerialNumberNotDefined("It seems like Your system module for {} does not have "
                                                 "`serial_number` attribute, please review Your init file!"
                                                 .format(bts_type))

            log_step("Smod's serial number successfully detected.")

            if not smod.pdu_port:
                raise SmodNotConnectedToPdu("Your system module does not have any connection to existing PDU!"
                                            " Please fix it by defining `pdu_port` attribute.")

            log_step("PDU Port connected to system module detected.")

        log_result("{0} System modules validation has finished!".format(bts_type))

    def _validate_bbmod_units(self, bts_type):
        """
        Validates baseband modules' representation in __init__ testline configuration file. There must be
        certain assertions:
        1. All baseband modules must have ip's `addr` attribute defined (not a None value also);
        2. If lmi boards will be detected in every RU object, then all baseband modules must have `rus` attribute
           with connection made to proper radio unit objects.
        3. BBmod's hardware_type parameter is not None.
        4. BBmod's serial_number parameter is not None.
        5. System module equal ASOE skips baseband modules verification.

        :param bts_type: Type of BTS in which baseband modules are connected - might be "GNB" or "ENB".
        :type bts_type: str
        :raises: CapacityUnitAddrNotFound exception if first condition won't be met.
        :raises: CapacityUnitsRusNotFound exception if second condition won't be met.
        :raises: BBmodHwTypeNotDefined exception if bbmod's hardware_type parameter is not set.
        :raises: BBmodSerialNumberNotDefined exception if bbmod's serial_number parameter is not set.
        """
        log_operation("Validating {0} Baseband Modules...".format(bts_type))

        bbmods = []
        list_of_smods = self.gnb_smods if bts_type == "GNB" else self.enb_smods

        for smod in list_of_smods:
            if smod.hardware_type in ['ASOE', 'ASOG', 'ASOH'] or isinstance(smod, CoreUnit):
                log_result(f"Your system module is equal to {smod.hardware_type} core units. "
                           f"Baseband module verification skipped.")
            else:
                for bbmod in smod.capacity_units:
                    bbmods.append(bbmod)

        log_env_state("Baseband modules read from __init__: {0}".format(bbmods))
        for bbmod in bbmods:

            log_iteration("Baseband module that is being validated: {0}".format(bbmod))

            if not hasattr(bbmod, 'addr') or not bbmod.addr:
                raise CapacityUnitAddrNotFound("Your baseband module does not have ip's `addr` attribute properly "
                                               "defined! Please fix this and try again.")

            if bts_type == 'GNB' and not bbmod.hardware_type:
                raise BBmodHwTypeNotDefined("It seems like Your baseband module does not have `hardware_type` "
                                            "attribute, please review Your init file!")

            log_step("Baseband module's ip address successfully detected.")

            if bts_type == 'GNB' and not bbmod.serial_number:
                raise BBmodSerialNumberNotDefined("It seems like Your baseband module does not have `serial_number` "
                                                  "attribute, please review Your init file!")

            log_step("Baseband module's serial number successfully detected.")

            if self.lmi_connected and bts_type == 'GNB':
                if not hasattr(bbmod, 'rus') or not bbmod.rus:
                    raise CapacityUnitsRusNotFound("LMI boards were detected for all RUs but there is no connection "
                                                   "between baseband modules and radio units (no `rus` attribute or is"
                                                   " None) so there is no way to detect proper Test PC - please "
                                                   "define `rus` for every baseband module and try again!")

                log_step("Radio units list has been verified for baseband module")

        log_result("{0} baseband modules validation has finished!".format(bts_type))

    def _validate_gnb_ru_units(self):
        """
        Validates radio units attached in `rus` list in GNB's DU object.
        Some conditions must be met to pass validation:

        1. Radio units' list is not empty;
        2. All radio unit objects in list must have `pdu_port` defined (not empty);
        3. All radio unit objects must have unique `pdu_port`;
        4. All radio unit objects must have attribute `radio_type` configured.
        5. All radio unit objects must have attribute 'serial_number' configured.

        :raises: NoGnbRusDetected exception if first condition won't be met.
        :raises: NoPduPortDefiniedForRu exception if second condition won't be met.
        :raises: NotUniqueRuPduPortDetected exception if third condition won't be met.
        :raises: RadioTypeNotConfigured exception if fourth condition won't be met.
        :raises: RmodHwTypeNotDefined exception if fifth condition won't be met.
        """
        log_operation("Validating list of GNB radio units...")

        if not self.gnb_rus:
            raise NoGnbRusDetected("There is no `rus` list defined inside GNB's object or there is an empty list - "
                                   "please fix Your init file and try again.")

        log_step("Radio units detected.")

        pdu_ports = []

        for ru in self.gnb_rus:
            log_iteration("Iterating over ru: {0}".format(ru))

            if not ru.radio_type:
                raise RadioTypeNotConfigured("There is no radio_type param configured for RU with "
                                             "init index: {}".format(self.gnb_rus.index(ru)))

            port = ru.pdu_port
            log_env_state("Found pdu port in ru object: {0}".format(port))

            if not ru.serial_number:
                raise RmodSerialNumberNotDefined("There is no serial_number param configured for RU with "
                                                 "init index: {}".format(self.gnb_rus.index(ru)))

            log_step("Radio module's serial number successfully detected.")

            if not port:
                raise NoPduPortDefiniedForRu("It seems like Your testline configuration file has not definied PDU port"
                                             " for RU: {0}, please fix it.".format(ru.radio_type))

            if port in pdu_ports:
                raise NotUniqueRuPduPortDetected("{0} pdu port has been duplicated among different RUs"
                                                 "".format(port))

            log_step("Adding pdu port to list of unique ports...")
            pdu_ports.append(ru.pdu_port)
            log_env_state("List of unique pdu ports so far: {0}".format(pdu_ports))

        log_result("GNB's radio units has been verified!")

    def _validate_enb_ru_units(self):
        """
        Validates radio units attached in `rms` list in eNB object from taf.config.testline.enb.
        Some conditions must be met to pass validation:

        1. All radio unit objects in list must have `pdu_port` defined (not empty);
        2. All radio unit objects must have unique `pdu_port`;
        3. All radio unit objects must have attribute `radio_type` configured.
        4. All radio unit objects must have attribute 'serial_number' configured.

        :raises: NoPduPortDefiniedForRu exception if first condition won't be met.
        :raises: NotUniqueRuPduPortDetected exception if second condition won't be met.
        :raises: RadioTypeNotConfigured exception if third condition won't be met.
        :raises: RmodHwTypeNotDefined exception if fourth condition won't be met.
        """
        log_operation("Validating list of eNB radio units...")

        pdu_ports = []

        for ru in self.enb_rus:
            log_iteration("Iterating over eNB's ru: {0}".format(ru))

            if not ru.radio_type:
                raise RadioTypeNotConfigured("There is no radio_type param configured for eNB's RU with "
                                             "init index: {}".format(self.enb_rus.index(ru)))

            port = ru.pdu_port
            log_env_state("Found pdu port in eNB's ru object: {0}".format(port))

            if not ru.serial_number:
                raise RmodSerialNumberNotDefined("There is no serial_number param configured for eNB's RU with "
                                                 "init index: {}".format(self.enb_rus.index(ru)))

            log_step("eNB's radio module's serial number successfully detected.")

            if not port:
                raise NoPduPortDefiniedForRu("It seems like Your testline configuration file has not definied PDU port"
                                             " for eNB's RU: {0}, please fix it.".format(ru.radio_type))

            if port in pdu_ports:
                raise NotUniqueRuPduPortDetected("{0} pdu port has been duplicated among different RUs"
                                                 "".format(port))

            log_step("Adding pdu port to list of unique ports...")
            pdu_ports.append(ru.pdu_port)
            log_env_state("List of unique pdu ports so far: {0}".format(pdu_ports))

        log_result("eNB's radio units have been verified!")

    def _validate_pdus(self):
        """
        Validates if pdus list in __init__ testline configuration file meet certain conditions:

        1. It is not empty;
        2. If there will be any ATEN PDU object, validator will check if there is no `model`
           attribute mistakenly defined.

        :raises: NoPdusDetected exception if first condition won't be met.
        :raises: AtenModelAttributeError exception if second condition won't be met.
        """
        log_operation("PDUs validation begins.")

        log_env_state("PDUs list found in __init__: {0}".format(self.pdus))

        if not self.pdus:
            raise NoPdusDetected("No PDUs have been detected in Your testline configuration file!")

        for pdu in self.pdus:
            log_iteration("Iterating over pdu: {0}".format(pdu))

            if isinstance(pdu, ATEN) and pdu.model:
                raise AtenModelAttributeError("Your ATEN PDU: ({0}) has defined `model` attribute which is forbidden!"
                                              "Please remove the attribute in your init file and try again."
                                              .format(pdu))

        log_result("PDUs validation finished.")

    def _is_lmi_connected_to_all_rus(self):
        """
        Checks if lmi board is connected to all radio units listed in GNB's DU object under `rus` attribute so
        validator will be able to also verify if structure of __init__ file for RUs lmi board log collection is
        appropriate.

        :return: True, if all RUs have `lmp_connection` and/or `lmi` attributes, False otherwise
        :rtype: bool
        """
        return all([ru.lmp_connection or ru.lmi for ru in self.gnb_rus])

    def _validate_second_config_gnbs_are_subset(self, second_config_gnbs):
        if second_config_gnbs:
            global_and_instance_bts_ids = [sorted((gnb.global_bts_id, gnb.instance_id)) for gnb in self.gnbs]
            for second_config_gnb in second_config_gnbs:
                if sorted((second_config_gnb.instance_id, second_config_gnb.global_bts_id)) \
                        not in global_and_instance_bts_ids:
                    raise SecondConfigGnbNotInDefaultConfig(
                        "Could not find GNB from second config with instance_id: {} and global_bts_id: {} in "
                        "default config".format(second_config_gnb.instance_id, second_config_gnb.global_bts_id))
            log_result("Validation of second config's GNBs succeeded.")
            return True
        return True

    def _validate_second_config_enbs_are_subset(self, second_config_enbs):
        if second_config_enbs:
            global_and_instance_bts_ids = [sorted((enb.global_bts_id, enb.instance_id)) for enb in self.enbs]
            for second_config_enb in second_config_enbs:
                if sorted((second_config_enb.instance_id, second_config_enb.global_bts_id)) \
                        not in global_and_instance_bts_ids:
                    raise SecondConfigEnbNotInDefaultConfig(
                        "Could not find ENB from second config with instance_id: {} and global_bts_id: {} in "
                        "default config".format(second_config_enb.instance_id, second_config_enb.global_bts_id))
            log_result("Validation of second config's ENBs succeeded.")
            return True
        return True

    def _validate_second_config_test_pcs_are_subset(self, second_config_test_pcs):
        test_pcs_addr = [test_pc.default_ssh_connection_details.addr for test_pc in self.test_pcs]
        for test_pc in second_config_test_pcs:
            if test_pc.default_ssh_connection_details.addr not in test_pcs_addr:
                raise SecondConfigTestPcAddrNotFound("Could not find test pc from second config with addr: {} in "
                                                     "default config.".
                                                     format(test_pc.default_ssh_connection_details.addr))
        log_result("Validation of second config's test pcs succeeded.")
        return True

    def _validate_second_config_smods_are_subset(self, second_config_smods, bts_type):
        gnb_smods_serial_numbers = [smod.serial_number for smod in self.gnb_smods]
        enb_smods_serial_numbers = [smod.serial_number for smod in self.enb_smods]
        smods_serial_numbers = gnb_smods_serial_numbers + enb_smods_serial_numbers

        for smod in second_config_smods:
            if smod.serial_number not in smods_serial_numbers:
                raise SecondConfigSmodNotFound("Could not find smod with serial number: {} from second config "
                                               "in default config.".format(smod.serial_number))
        log_result("Validation of second config's {} smods succeeded.".format(bts_type))
        return True

    def _validate_second_config_bbmods_are_subset(self, second_config_bbmods):
        bbmods_serial_numbers = [bbmod.serial_number for bbmod in self._get_all_bbmods()]
        for bbmod in second_config_bbmods:
            if bbmod.serial_number not in bbmods_serial_numbers:
                raise SecondConfigBbmodNotFound("Could not find bbmod with serial number: {} from second config "
                                                "in default config.".format(bbmod.serial_number))
        log_result("Validation of second config's bbmods succeeded.")
        return True

    def _validate_second_config_rmods_are_subset(self, second_config_rmods, bts_type):
        gnb_rmods_serial_numbers = [rmod.serial_number for rmod in self.gnb_rus]
        enb_rmods_serial_numbers = [rmod.serial_number for rmod in self.enb_rus]
        rmods_serial_numbers = gnb_rmods_serial_numbers + enb_rmods_serial_numbers
        for rmod in second_config_rmods:
            if rmod.serial_number not in rmods_serial_numbers:
                raise SecondConfigRmodNotFound("Could not find rmod with serial number: {} from second config "
                                               "in default config.".format(rmod.serial_number))
        log_result("Validation of second config's {} rmods succeeded.".format(bts_type))
        return True

    def _get_all_bbmods(self):
        all_smods = self.gnb_smods + self.enb_smods
        bbmods = []
        for smod in all_smods:
            if isinstance(smod, CoreUnit):
                continue
            bbmods.extend(smod.capacity_units)

        return bbmods

    def _get_bts_list(self):
        bts_list = []
        if self.gnbs:
            bts_list.append('GNB')
        if self.enbs:
            bts_list.append('ENB')
        if not bts_list:
            raise CouldNotFindBtsType("Could not find gnbs nor enbs objects. Please review your init file.")
        return bts_list
